def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    current = chain_dict.get('a', [])
    result = []

    while current:
        next_item = current.pop()
        result.append(next_item)

        if next_item in chain_dict:
            current.extend(chain_dict[next_item])

    return ','.join(result)
